    {impl : QueryImpl oSpec (StateT σ ProbComp)} {lang₁ : Set Stmt₁} {lang₂ : Set Stmt₂}
    {V₁ : Verifier oSpec Stmt₁ Stmt₂ pSpec₁} {verify : Stmt₁ → pSpec₁.FullTranscript → Stmt₂}
