      let r₁ ← liftAppendLeft rightSpec (leftProver.run () ())
      let r₂ ← liftAppendRight leftSpec (rightProver.run r₁.2.1 r₁.2.2)
      pure (r₁.1 ++ₜ r₂.1, r₂.2)))

theorem message_opening_effectful : (effectfulLeft.append mixedRight).run () () = (do
