      liftAppendLeft messageThenChallenge (effectfulLeft.run () ())
    let ⟨tr₂, stmt₃, wit₃⟩ ← liftAppendRight !p[] (mixedRight.run stmt₂ wit₂)
    return ⟨tr₁ ++ₜ tr₂, stmt₃, wit₃⟩)

